import { profileSelector } from './profile-view.js';
import { selectedProfile } from './profile-store.js';
import { escapeHtml as e, time } from './store.js';
import { documentState } from './document-state.js';
import { reviewItems, targetText, currentDerived } from './revision-store.js';
import { diffWords } from './evidence.js';
import { icon } from './icons.js';
const button = (action, label, id, cls = '', extra = '') => `<button class="button ${cls}" data-action="${action}" ${id ? `data-id="${e(id)}"` : ''} ${extra}>${label}</button>`;
const range = r => `${time(r[0])}–${time(r[1])}`;
const risk = value => `<span class="risk-label risk-${value.level.toLowerCase()}">${e(value.level)} risk</span>`;
const tag = label => `<span class="risk-tag">${e(label)}</span>`;
function diffView(before, after) {
  const d = diffWords(before || '', after || '');
  const text = (tokens, side) => tokens.map(t => `<span class="${t.changed ? side === 'before' ? 'diff-removed' : 'diff-added' : ''}">${e(t.text)}</span>`).join('');
  return `<div class="review-diff"><div><h4>Current / hypothesis A</h4><p>${text(d.left, 'before') || '<span class="muted">Document gap</span>'}</p></div><div><h4>Proposed / hypothesis B</h4><p>${text(d.right, 'after')}</p></div></div>`;
}
function candidate(s, id, item) {
  const a = s.attempts.find(a => a.id === id), p = a && s.spans.find(p => p.id === a.spanId); if (!a) return '';
  const text = targetText(a, p);
  return `<article class="review-candidate"><header><strong>${e(a.id)}</strong><span>${e(a.model)}</span></header><div class="review-candidate-meta"><span>${e(a.jobId)}</span><span>Input ${range(a.input)}</span><span>${e(a.contextId)}</span></div><p>${e(text ?? a.resultText)}</p><footer>${item.kind === 'Disagreement' ? button('review-choose', 'Choose source & propose update', id, 'small-button primary', `data-review-id="${e(item.id)}"`) : ''}${button('activity-reference', 'Inspect attempt', id, 'text-button small-button')}</footer></article>`;
}
export function visibleReview(s) {
  return reviewItems(s).filter(i => (s.reviewFilter === 'All' || i.state === s.reviewFilter) && (s.reviewScope === 'all' || i.dictationId === s.reviewScope) && (s.reviewRisk === 'All' || i.risk.level === s.reviewRisk) && (i.title + ' ' + i.risk.tags.join(' ') + ' ' + s.dictations.find(d => d.id === i.dictationId)?.title).toLowerCase().includes(s.reviewSearch.toLowerCase()));
}
export function reviewView(s) {
  const all = reviewItems(s), items = visibleReview(s), item = items.find(i => i.id === s.selectedReviewId) || items[0], dictation = item && s.dictations.find(d => d.id === item.dictationId);
  const attemptIds = item?.candidates || (item?.evidence || []).map(id => s.requests.find(r => r.id === id)?.attemptId || id);
  return `<main id="document" class="review-console" tabindex="-1"><div class="review-topline"><div><span class="overline">DOCUMENT QUALITY</span><h1>Semantic review</h1></div><div class="review-counts"><span><strong>${all.filter(i => i.state === 'Pending' && i.risk.level === 'High').length}</strong> high risk</span><span><strong>${all.filter(i => i.state === 'Pending').length}</strong> pending</span></div><span class="review-heuristic-label">Heuristic priority · evidence still requires review</span></div><div class="review-layout"><aside class="review-browser"><div class="job-search">${icon('search')}<input id="review-search" value="${e(s.reviewSearch)}" placeholder="Find dictation or risk…" aria-label="Search review items"/></div><div class="review-filters"><select data-review-setting="reviewScope" aria-label="Review dictation"><option value="all">All dictations</option>${s.dictations.map(d => `<option value="${d.id}" ${s.reviewScope === d.id ? 'selected' : ''}>${e(d.title)}</option>`).join('')}</select><div><select data-review-setting="reviewFilter" aria-label="Review status">${['Pending', 'Resolved', 'All'].map(v => `<option ${s.reviewFilter === v ? 'selected' : ''}>${v}</option>`).join('')}</select><select data-review-setting="reviewRisk" aria-label="Semantic risk">${['All', 'High', 'Medium', 'Low'].map(v => `<option ${s.reviewRisk === v ? 'selected' : ''}>${v}</option>`).join('')}</select></div></div><div class="review-list">${items.map(i => `<button class="review-list-item ${i.id === item?.id ? 'selected' : ''}" data-action="select-review" data-id="${e(i.id)}"><div>${risk(i.risk)}<span>${e(i.kind)}</span></div><strong>${e(i.title)}</strong><small>${e(s.dictations.find(d => d.id === i.dictationId)?.title)}</small><div class="review-list-tags">${i.risk.tags.map(tag).join('')}</div><span class="mono">${range(i.range)}</span></button>`).join('') || '<div class="technical-empty">No matching review items.</div>'}</div><div class="review-browser-note">Priority reflects changed wording. Model agreement does not establish correctness.</div></aside><section class="review-detail-scroll">${item ? `<article class="review-detail"><div class="review-detail-heading"><div><div class="overline">${e(item.kind)} · ${range(item.range)}</div><h2>${e(item.title)}</h2><button class="review-document-link" data-action="select-source" data-id="${dictation.id}">${e(dictation.title)} ${icon('chevron')}</button></div>${risk(item.risk)}</div><div class="review-tags">${item.risk.tags.map(tag).join('')}</div><p class="review-explanation">${e(item.explanation)}</p><div class="review-audio-reference"><div>${icon('wave')}<strong>Target audio ${range(item.range)}</strong><span>Surrounding input ranges are retained per attempt.</span></div>${button('review-audio', 'Open audio interval', item.id, 'small-button')}</div>${diffView(item.before, item.after)}<div class="review-primary-actions">${item.state === 'Resolved' ? '<span class="status-label status-complete"><i></i>Resolved · evidence retained</span>' : item.kind === 'Revision' ? `${button('accept-change', 'Accept suggestion', item.changeId, 'primary')}${button('dismiss-change', 'Keep current text', item.changeId, '')}` : item.kind === 'Assembly' ? `${button('review-apply-assembly', 'Apply document update', item.id, 'primary')}${button('assembly-dictation', 'Open assembly plan', item.dictationId, '')}` : '<span>Choose a source below. The document update is proposed separately.</span>'}</div>${item.kind === 'Revision' ? `<details class="review-corrector-input"><summary>Corrector profile & frozen input</summary><div class="profile-model-line"><span>${e(item.model)}</span><span>${item.profileSnapshot ? e(item.profileSnapshot.name) + ' · v' + item.profileSnapshot.version : 'Historical proposal · no reusable profile link recorded'}</span><span>Suggestions only</span></div>${item.inputContext ? `<pre class="code-block">${e(JSON.stringify({ profile: item.profileSnapshot, input: item.inputContext }, null, 2))}</pre>` : ''}</details>` : ''}${attemptIds.length ? `<h3 class="review-section-title">Supporting recognition evidence</h3><div class="review-candidates">${attemptIds.map(id => candidate(s, id, item)).join('')}</div>` : '<div class="technical-note">This proposal derives from the current document snapshot. No new ASR result is implied.</div>'}<div class="review-policy-note">Document application checks the captured base text or version. Manual edits remain protected. Source hypotheses are preserved.</div></article>` : '<div class="technical-empty">No pending review items in this scope.</div>'}</section></div></main>`;
}
export function assemblyBody(s) {
  const p = s.assemblies.find(p => p.id === s.selectedAssemblyId), ds = documentState(s), d = s.dictations.find(d => d.id === s.dictationId);
  return `<div class="assembly-intro"><div><strong>${e(d.title)}</strong><span>Working document v${ds.version}</span></div><label>Scope<select id="assembly-scope"><option value="gaps" ${s.assemblyMode === 'gaps' ? 'selected' : ''}>Fill document gaps</option><option value="refresh" ${s.assemblyMode === 'refresh' ? 'selected' : ''}>Refresh mapped passages</option></select></label>${button('rebuild-assembly', 'Build preview', null, 'small-button')}</div><p class="technical-note">Assembly uses explicit target-text mappings, keeps audio order, and excludes surrounding input-window context. Competing hypotheses require a source choice.</p>${p && p.dictationId === s.dictationId ? `<div class="assembly-version ${p.expectedVersion !== ds.version ? 'stale' : ''}"><span>${e(p.id)} · base v${p.baseVersion}</span><strong>${p.expectedVersion !== ds.version ? 'Document changed · rebuild required' : 'Preview matches current version'}</strong></div><div class="assembly-steps">${p.steps.map(step => `<article class="assembly-step operation-${step.operation.toLowerCase().replace(/ /g, '-')} ${step.state === 'applied' ? 'applied' : ''}"><header><div><strong>${e(step.operation)}</strong><span>${e(step.spanId)} · ${range(step.target)}</span></div><span>${step.state === 'applied' ? 'Applied' : step.risk ? risk(step.risk) : e(step.state)}</span></header><p>${e(step.reason)}</p>${step.after !== null && !['Unchanged', 'Existing text'].includes(step.operation) ? diffView(step.before, step.after) : ''}<footer>${step.attemptId ? `${button('activity-reference', e(step.attemptId) + ' · provenance', step.attemptId, 'text-button small-button')}` : ''}${step.operation === 'Conflict' ? button('open-span-review', 'Resolve disagreement', step.spanId, 'small-button') : ''}${step.state === 'pending' && ['Insert', 'Replace'].includes(step.operation) ? button('apply-assembly-step', 'Apply passage', step.id, 'small-button primary', p.expectedVersion === ds.version ? '' : 'disabled') : ''}</footer></article>`).join('') || '<div class="technical-empty">No successful mapped recognition results are available.</div>'}</div>` : '<div class="technical-empty">Build an assembly preview for this dictation.</div>'}`;
}
export function revisionBody(s) {
  const ds = documentState(s), modes = [['repair', 'Recognition repair', 'Use recognition evidence to correct misheard wording. Changes are reviewed before application.'], ['cleanup', 'Cleanup', 'Remove fillers and adjust formatting while preserving substantive wording.'], ['editorial', 'Editorial revision', 'Propose rephrasing or reorganization for human review. Recognition evidence and primer inputs remain independent.']];
  return `<label class="setting-field"><span>Corrector profile</span>${profileSelector(s, 'corrector', s.dictationId, 'revision-profile')}</label><div class="human-write-policy">Suggestions only. Document text changes after human acceptance.</div><div class="revision-modes">${modes.map(([id, title, help]) => `<button class="revision-mode ${s.revisionMode === id ? 'selected' : ''}" data-action="revision-mode" data-value="${id}"><span>${s.revisionMode === id ? icon('check') : icon(id === 'repair' ? 'wave' : id === 'cleanup' ? 'sliders' : 'edit')}</span><div><strong>${title}</strong><p>${help}</p></div></button>`).join('')}</div><div class="revision-input-info"><span>Input: working document v${ds.version}</span><span>Model: ${e(selectedProfile(s, 'corrector').model)} · profile v${selectedProfile(s, 'corrector').version}</span><span>Primer: v${s.primer.version}</span></div><div class="quiet-note">The mock-up uses separate fixture suggestions for each mode. Edited passages without a matching fixture remain unchanged.</div>${ds.derived.length ? `<h3 class="review-section-title">Derived documents</h3><div class="derived-list">${ds.derived.map(d => `<div><span><strong>${e(d.name)}</strong><small>From v${d.baseVersion} · ${d.changed} fixture rewrites · ${e(d.model)}</small></span>${button('open-derived', 'Open draft', d.id, 'small-button')}</div><details class="derived-context"><summary>Frozen corrector input · ${e(d.id)}</summary><pre class="code-block">${e(JSON.stringify(d.inputContext, null, 2))}</pre></details>`).join('')}</div>` : ''}<h3 class="review-section-title">Application journal</h3><div class="application-journal">${ds.journal.slice(-8).reverse().map(j => `<div><time>${e(j.time)}</time><strong>${e(j.action)} · ${e(j.outcome)}</strong><p>${e(j.detail)}</p></div>`).join('') || '<p class="technical-note">Document operations will be recorded here.</p>'}</div><details class="revision-history"><summary>Document revisions · ${ds.history.length}</summary>${ds.history.slice().reverse().map(v => `<div><strong>v${v.version} · ${e(v.type)}</strong><span>${e(v.time)} · ${v.blocks.length} passages</span></div>`).join('')}</details>`;
}
export function provenanceBody(s) {
  const b = (s.documentMode === 'derived' ? currentDerived(s)?.blocks : s.documents[s.dictationId])?.find(b => b.id === s.selectedBlockId), p = b?.provenance;
  return b ? `<div class="provenance-heading"><strong>Passage ${range([b.start, b.end])}</strong><span>${e(p?.kind || 'Unmapped source')}</span></div><p class="technical-note">${e(p?.mapping || p?.source || 'Document-origin text; no precise audio-to-word mapping claimed.')}</p>${(p?.attemptIds || []).map(id => candidate(s, id, { kind: 'Provenance' })).join('') || '<p class="technical-note">No exact attempt link is recorded for this initial passage.</p>'}<pre class="code-block">${e(JSON.stringify(p || {}, null, 2))}</pre>` : '<div class="technical-empty">Select a document passage.</div>';
}
